#!/usr/bin/env python3
"""Render GitOps Day 2 manifests from platform contract."""

import argparse
import sys
from pathlib import Path

HEADER_PREFIX = "# Generated by render-gitops.py"

from resolver import resolve, validate, has_contract_inputs
from gitops_exceptions import rendered_register
from gitops_renderer import render_gitops
from gitops_renderer.common import _application_summary


def _cleanup_stale_generated_files(out: Path, desired_paths: set[str]) -> int:
    """Remove generated files that are no longer emitted by the renderer."""
    if not out.exists():
        return 0

    removed = 0
    for fp in sorted(out.rglob("*")):
        if not fp.is_file():
            continue
        rel = fp.relative_to(out).as_posix()
        if rel in desired_paths:
            continue
        try:
            content = fp.read_text()
        except UnicodeDecodeError:
            continue
        if content.startswith(HEADER_PREFIX):
            fp.unlink()
            removed += 1

    for dp in sorted((p for p in out.rglob("*") if p.is_dir()), reverse=True):
        try:
            dp.rmdir()
        except OSError:
            pass

    return removed


def main() -> None:
    parser = argparse.ArgumentParser(description="Render GitOps Day 2 manifests from platform contract")
    parser.add_argument("--root", type=Path, default=None)
    parser.add_argument("--cluster", type=str, default=None)
    parser.add_argument("--output", type=Path, default=None)
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()

    root = args.root
    if root is None:
        script_dir = Path(__file__).resolve().parent
        candidate = script_dir.parent
        if has_contract_inputs(candidate):
            root = candidate
        else:
            print("ERROR: Cannot find platform root. Use --root.", file=sys.stderr)
            sys.exit(2)

    try:
        platform = resolve(root)
    except ValueError as e:
        print(f"ERROR: {e}", file=sys.stderr)
        sys.exit(2)

    errors = validate(platform)
    if errors:
        print(f"Validation failed ({len(errors)} errors):", file=sys.stderr)
        for err in errors:
            print(f"  - {err}", file=sys.stderr)
        sys.exit(1)

    clusters = platform.clusters
    if args.cluster:
        clusters = [c for c in clusters if c.name == args.cluster]
        if not clusters:
            print(f"ERROR: cluster {args.cluster!r} not found", file=sys.stderr)
            sys.exit(2)

    if not platform.defaults:
        print("ERROR: No defaults file found in data/defaults/. Cannot render.", file=sys.stderr)
        sys.exit(2)

    all_files: dict[str, str] = {}

    for cluster in clusters:
        files = render_gitops(cluster, platform.fabric.fabric_asn, platform.defaults)

        if not files:
            print(f"# Skipping {cluster.name} (hostedControlPlanes feature disabled)", file=sys.stderr)
            continue

        print(f"# GitOps composition for {cluster.name}", file=sys.stderr)
        print("# Required capabilities: core", file=sys.stderr)
        if cluster.network_type == "Cilium":
            print("# Required capabilities: isovalent", file=sys.stderr)
        if cluster.features.get("hostedControlPlanes", False):
            print("# Required capabilities: hcp-management", file=sys.stderr)
        enabled_addons = [name for name, enabled in sorted(cluster.gitops_addons.items()) if enabled]
        print(f"# Optional add-ons enabled: {', '.join(enabled_addons) if enabled_addons else 'none'}", file=sys.stderr)
        for wave, name, path, _ in _application_summary(files):
            print(f"#   wave {wave:>3}  {name} -> {path}", file=sys.stderr)

        if args.dry_run:
            print(f"# === GitOps tree for {cluster.name} ({len(files)} files) ===\n")
            for fpath in sorted(files.keys()):
                print(f"# --- {fpath} ---")
                print(files[fpath])
            print(f"\n# Total: {len(files)} files", file=sys.stderr)
        else:
            all_files.update(files)

    try:
        register_files = rendered_register(root)
    except ValueError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        sys.exit(2)

    if args.dry_run:
        for fpath in sorted(register_files):
            print(f"# --- {fpath} ---")
            print(register_files[fpath])
    else:
        all_files.update(register_files)

    if not args.dry_run:
        out = args.output or (
            root / "generated" / "repos" / platform.defaults.identity["generatedRepos"]["gitops"]
        )
        out.mkdir(parents=True, exist_ok=True)
        removed = 0 if args.cluster else _cleanup_stale_generated_files(out, set(all_files.keys()))
        for fpath, content in all_files.items():
            fp = out / fpath
            fp.parent.mkdir(parents=True, exist_ok=True)
            fp.write_text(content)
        print(f"Written {len(all_files)} files to {out}/")
        if removed:
            print(f"Removed {removed} stale generated files from {out}/")


if __name__ == "__main__":
    main()
